// Üretilen dosya: tool/ozgun/uret.py. Matematik · Sayma, olasılık ve kombinatorik problemleri (zor).
const ozMathematics14Zor = <(String, String, List<String>, String)>[
  ('Rakamları birbirinden farklı olan üç basamaklı kaç doğal sayı 5 ile tam bölünür?', '136', ['144', '128', '1360'], 'Birler 0 ise 9 · 8 = 72 sayı vardır. Birler 5 ise yüzler basamağında 0 ve 5 olamaz (8 seçenek), onlar basamağında 8 seçenek kalır: 64. Toplam 136.'),
  ('Rakamları soldan sağa kesin biçimde azalan kaç tane dört basamaklı doğal sayı vardır?', '210', ['5040', '126', '252'], 'Birbirinden farklı 4 rakam seçildiğinde bunların azalan dizilişi tek türlüdür; sıfır en sona düştüğü için sorun çıkmaz. C(10, 4) = 210.'),
  ('Rakamları birbirinden farklı olan dört basamaklı kaç tek doğal sayı vardır?', '2240', ['22400', '2250', '2160'], 'Birler basamağı 5 seçenek; binler basamağı 0 ve birler rakamı hariç 8 seçenek; yüzler 8, onlar 7 seçenek. 5 · 8 · 8 · 7 = 2240.'),
  ('2 matematik, 3 fizik ve 2 kimya kitabı bir rafa, aynı dersin kitapları yan yana olacak biçimde dizilecektir. Kitapların hepsi birbirinden farklı ise kaç farklı dizilim yapılabilir?', '144', ['72', '36', '1440'], 'Üç ders grubu 3! = 6 biçimde dizilir; grup içlerinde 2! · 3! · 2! = 24 düzen vardır. 6 · 24 = 144.'),
  ('7 kişi bir sıraya dizilecektir. Ayşe ile Cem\'in arasında tam iki kişi bulunacağına göre kaç farklı sıralama vardır?', '960', ['720', '1440', '480'], 'Ayşe ile Cem 4 farklı konum çiftinden birine (1–4, 2–5, 3–6, 4–7) 2 sıralamayla yerleşir; kalan 5 kişi 5! = 120 biçimde dizilir. 4 · 2 · 120 = 960.'),
  ('8 kişi 8 koltuklu bir sıraya oturacaktır. Belirli üç kişinin ardışık üç koltukta birlikte oturmadığı kaç farklı oturuş vardır?', '36000', ['4320', '40320', '35280'], 'Toplam 8! = 40320 oturuş vardır. Üçlünün bir arada olduğu durum 3! · 6! = 4320 tanedir. 40320 − 4320 = 36000.'),
  ('8 kişi yuvarlak bir masa etrafına oturacaktır. Ela ile Faruk tam karşı karşıya oturacağına göre kaç farklı oturma düzeni vardır?', '720', ['5040', '1440', '40320'], 'Ela sabitlenince Faruk\'un yeri belli olur (karşı koltuk); kalan 6 kişi 6! = 720 biçimde oturur.'),
  ('15 öğrenci, her biri 5 kişilik ve adı olmayan üç gruba kaç farklı biçimde ayrılabilir?', '126126', ['1261260', '3003', '252252'], 'Adlı gruplar için C(15, 5) · C(10, 5) · 1 = 3003 · 252 = 756756 bulunur. Gruplar adsız olduğundan 3! = 6\'ya bölünür: 126126.'),
  ('8 kişilik bir gruptan 4 kişilik bir ekip kuruluyor. Zeynep ile Mert ya ekipte birlikte yer alacak ya da ikisi de dışarıda kalacaktır. Kaç farklı ekip kurulabilir?', '30', ['15', '35', '70'], 'İkisi birlikteyse kalan 6 kişiden 2\'si seçilir: C(6, 2) = 15. İkisi de yoksa 6 kişiden 4\'ü seçilir: C(6, 4) = 15. Toplam 30.'),
  ('Dışbükey bir sekizgenin köşelerinden oluşturulan üçgenlerden, kenarlarından hiçbiri sekizgenin bir kenarı olmayanlar kaç tanedir?', '16', ['56', '40', '24'], 'Toplam C(8, 3) = 56 üçgen vardır. İki kenarı çokgen kenarı olanlar 8, tam bir kenarı çokgen kenarı olanlar 8 · 4 = 32 tanedir. 56 − 8 − 32 = 16.'),
  ('x + y + z ≤ 5 eşitsizliğini sağlayan negatif olmayan tam sayı üçlüleri (x, y, z) kaç tanedir?', '56', ['21', '35', '84'], 'Bir t değişkeni ekleyerek x + y + z + t = 5 elde edilir; negatif olmayan çözüm sayısı C(8, 3) = 56.'),
  ('Pascal üçgeninde C(5,0) + C(4,1) + C(3,2) toplamı bir köşegen boyunca alınan sayıları toplar. Bu toplam hangi sayı dizisinin bir terimini verir?', 'Fibonacci sayılarından biri olan 8', ['Üçgen sayılardan biri olan 21', 'Kare sayıların 8. terimi olan 64', 'Asal sayıların 8. terimi olan 19'], 'Köşegen toplamları Fibonacci sayılarını verir: 1 + 4 + 3 = 8 ve 8, 1, 1, 2, 3, 5, 8 dizisinin bir terimidir.'),
  ('Yalnızca 1, 2 ve 3 rakamları kullanılarak, her biri en az bir kez geçecek biçimde yazılabilen dört basamaklı kaç doğal sayı vardır?', '36', ['360', '24', '48'], 'Tüm sayılar 3⁴ = 81\'dir. En çok iki rakam kullananlar çıkarılır: 81 − 3 · 2⁴ + 3 = 36.'),
  ('5 farklı mektup 3 farklı posta kutusuna, hiçbir kutu boş kalmayacak biçimde kaç farklı yolla atılabilir?', '150', ['243', '120', '180'], 'Tüm dağılımlar 3⁵ = 243\'tür. Boş kutu bırakanlar dahil etme-dışarda bırakmayla çıkarılır: 243 − 3 · 2⁵ + 3 = 150.'),
  ('Kenar uzunluğu 2 birim olan bir kare şeklindeki kâğıt parçasının içine 5 nokta konuyor. Bu noktalardan en az ikisinin arasındaki uzaklığın en çok √2 olduğu garanti midir?', 'Evet; kare 4 birim kareye bölünür ve ikisi aynı parçaya düşer', ['Hayır; noktalar köşelere yerleştirilebilir', 'Hayır; en az 9 nokta gerekir', 'Evet; ama yalnız noktalar kare içinde eşit aralıklıysa'], 'Kare, kenarı 1 olan 4 parçaya ayrılır. 5 nokta için en az iki nokta aynı parçada olur ve bir birim karedeki uzaklık en çok köşegen uzunluğu √2\'dir.'),
  ('Koordinat düzleminde yalnız sağa ve yukarı birer birim adımla (0, 0) noktasından (3, 3) noktasına, (1, 1) noktasından geçmeyen kaç farklı en kısa yol vardır?', '8', ['12', '20', '6'], 'Tüm yollar C(6, 3) = 20\'dir. (1, 1)\'den geçenler C(2, 1) · C(4, 2) = 2 · 6 = 12\'dir. 20 − 12 = 8.'),
  ('Bir merdiven her adımda 1 ya da 2 basamak çıkılarak 6 basamak tırmanılacaktır. Kaç farklı adım dizisi mümkündür?', '13', ['8', '21', '130'], 'Dizi sayıları Fibonacci kuralını izler: 1, 2, 3, 5, 8, 13 (basamak sayısı 1\'den 6\'ya). 6 basamak için 13 dizi vardır.'),
  ('Hiçbir yerinde ardışık iki 1 bulunmayan 6 bitlik kaç farklı ikili dizi vardır?', '21', ['32', '24', '127'], 'n bitlik uygun dizilerin sayısı Fibonacci kuralıyla artar: 2, 3, 5, 8, 13, 21 (n = 1\'den 6\'ya). 6 bit için 21 dizi vardır.'),
  ('8 kişi, her biri tam bir arkadaşıyla çift olacak biçimde dört ikiliye kaç farklı yolla ayrılabilir?', '105', ['24', '2520', '1680'], 'İlk kişi 7 kişiyle, kalanlardan ilk kişi 5 kişiyle, sonra 3 kişiyle eşleşir; 7 · 5 · 3 · 1 = 105.'),
  ('Bir küpün 6 yüzü 6 farklı renkle boyanacaktır. Döndürüldüğünde birbirine çakışan boyamalar aynı sayılırsa kaç farklı küp elde edilir?', '30', ['720', '120', '24'], 'Toplam 6! = 720 boyama vardır. Küpün 24 farklı dönme konumu bulunduğundan boyamalar 24\'lü gruplara ayrılır: 720/24 = 30.'),
  ('Aynı anda atılan iki özdeş (ayırt edilemeyen) madeni paranın sonuçları listelenirse hangi sonuçlar elde edilir ve bu sonuçlar eşit olasılıklı mıdır?', '{YY, YT, TT}; eşit olasılıklı değildir, YT sonucu iki kat olasıdır', ['{YY, YT, TT}; üçü de 1/3 olasılıklıdır', '{YY, TT}; her biri 1/2 olasılıklıdır', '{YY, YT, TY, TT}; her birinin olasılığı 1/3\'tür'], 'Paralar ayırt edilemese de örnek uzayın eşit olasılıklı hâli YY, YT, TY, TT\'dir. Bu yüzden "bir yazı bir tura" sonucu 2/4 = 1/2 olasılıklıdır, YY ve TT ise 1/4\'er.'),
  ('52 kartlık standart bir desteden rastgele 5 kart çekiliyor. Çekilen elin dört ası da içermesi olasılığı kaçtır?', '1/54145', ['1/2598960', '1/13', '48/13'], 'Dört as sabittir; beşinci kart kalan 48 karttan biri olabilir. 48/C(52, 5) = 48/2598960 = 1/54145.'),
  ('Düzgün biçimde dönen bir çarkın okunun, çevre üzerinde önceden belirlenmiş tek bir noktada durma olasılığı 0\'dır. Bu bilgi hakkında hangisi doğrudur?', 'Olasılık 0 olsa da olay imkânsız olmak zorunda değildir', ['Olay imkânsızdır, çünkü olasılığı 0\'dır', 'Olasılık gerçekte çok küçük pozitif bir sayıdır', 'Çark aksiyomlara uymaz'], 'Sürekli örnek uzayda tek bir noktanın olasılığı 0\'dır ama ok yine de bir noktada durur; olasılığı 0 olan her olay imkânsız değildir.'),
  ('P(A) = 0,7 ve P(B) = 0,6 olduğuna göre P(A ∩ B) en az kaç olabilir?', '0,3', ['0,1', '0,4', '0,42'], 'P(A ∪ B) ≤ 1 olduğundan P(A ∩ B) = P(A) + P(B) − P(A ∪ B) ≥ 1,3 − 1 = 0,3.'),
  ('Bir torbada 5 kırmızı, 3 mavi top vardır. Geri konmadan art arda iki top çekiliyor. İlk topun rengine bakılmadığı bilinirse ikinci topun mavi olma olasılığı kaçtır?', '3/8', ['2/7', '3/7', '9/56'], 'Simetri nedeniyle her çekilişte mavi gelme olasılığı aynıdır: 3/8. Kesin hesap: (3/8)(2/7) + (5/8)(3/7) = 21/56 = 3/8.'),
  ('İki hilesiz zar atılıyor. "Toplamın 7 olması" ve "birinci zarın 2 gelmesi" olayları için aşağıdakilerden hangisi doğrudur?', 'Bağımsızdır; çünkü P(A ∩ B) = 1/36 = (1/6)(1/6)', ['Bağımsız değildir; çünkü birinci zar toplamı etkiler', 'Ayrıktır; çünkü ikisi aynı anda gerçekleşemez', 'Bağımlıdır; çünkü P(A | B) = 1/36'], 'P(toplam 7) = 1/6, P(birinci 2) = 1/6 ve birlikte gerçekleşme (2, 5) yalnız bir sonuçtur: 1/36. Çarpım eşitliği sağlandığından olaylar bağımsızdır.'),
  ('Bir e-posta kutusuna gelen iletilerin %20\'si istenmeyen (spam) iletidir. Filtre spam iletilerin %90\'ını, normal iletilerin %5\'ini "spam" olarak işaretlemektedir. "Spam" işaretli bir iletinin gerçekten spam olma olasılığı kaçtır?', '9/11', ['9/10', '9/110', '1/5'], 'İşaretli ileti olasılığı 0,2 · 0,9 + 0,8 · 0,05 = 0,18 + 0,04 = 0,22\'dir. Spam olanların payı 0,18/0,22 = 9/11.'),
  ('Bir torbada biri hilesiz, diğeri iki yüzü de yazı olan iki madeni para vardır. Rastgele seçilen para atılıyor ve yazı geliyor. Paranın iki yüzü yazı olan para olma olasılığı kaçtır?', '2/3', ['1/2', '3/4', '2/30'], 'Yazı gelme olasılığı (1/2) · 1 + (1/2) · (1/2) = 3/4\'tür. Hileli paranın payı (1/2)/(3/4) = 2/3.'),
  ('İki arkadaş 12:00 ile 13:00 arasında, birbirinden bağımsız ve rastgele bir anda buluşma yerine gelip 15 dakika bekledikten sonra gidiyor. Buluşma olasılığı kaçtır?', '7/16', ['7/160', '9/16', '1/2'], 'Varış zamanları arasındaki fark en çok 15 dakika olmalıdır. Kare alan 60², uygun olmayan iki üçgenin alanı 2 · (45²/2) = 45²; olasılık 1 − (45/60)² = 7/16.'),
  ('Bir ip rastgele iki noktadan kesilerek üç parçaya ayrılıyor. Bu üç parçadan bir üçgen kurulabilme olasılığı kaçtır?', '1/4', ['1/3', '1/2', '1/8'], 'Parçalarla üçgen kurulabilmesi için her parçanın toplam uzunluğun yarısından kısa olması gerekir. Bu koşul, kesme noktalarının oluşturduğu bölgenin dörtte birine denk gelir: 1/4.'),
  ('n nesne rastgele sıralanıyor. Kendi yerinde duran nesne sayısının beklenen değeri n\'den bağımsız olarak kaçtır?', '1', ['n/2', '1/n', '0'], 'Her nesnenin yerinde olma olasılığı 1/n\'dir. Beklenen değerin toplamsallığıyla n · (1/n) = 1 bulunur.'),
  ('7 kişi yan yana sıralanıyor. A, B ve C kişileri, aralarında başkaları olabilecek biçimde, soldan sağa A, B, C sırasında bulunacaktır. Kaç farklı sıralama vardır?', '840', ['5040', '720', '1260'], 'Üç kişinin kendi aralarındaki 3! = 6 sıralamadan yalnız biri istenir. 7!/6 = 5040/6 = 840.'),
  ('Bir sınıfta 4 kız ve 6 erkek öğrenci var. Kız ve erkek sayılarına göre ayrı ayrı sayılan üçlü seçimler C(4,0)C(6,3) + C(4,1)C(6,2) + C(4,2)C(6,1) + C(4,3)C(6,0) toplamıyla bulunuyor. Bu toplam hangi kombinasyona eşittir?', 'C(10, 3)', ['C(24, 3)', 'C(10, 4)', 'C(6, 3)'], 'Vandermonde özdeşliğine göre toplam C(4 + 6, 3) = C(10, 3) = 120\'dir; terimler 20 + 60 + 36 + 4 = 120 verir.'),
  ('Üç çift parantezin (her "(" için bir ")" bulunacak ve hiçbir yerde kapanan sayısı açılanı geçmeyecek biçimde) doğru yerleştirilmesinin kaç farklı yolu vardır?', '5', ['6', '8', '20'], 'Geçerli dizilişler ((())), (()()), (())(), ()(()), ()()() olmak üzere 5 tanedir; bu sayı 3. Katalan sayısıdır.'),
  ('Bir okul bahçesinde oyun oynamak için toplanan 6 çocuk, hiçbir ayrım gözetmeden ikişerli üç takıma ayrılacaktır. Bu bölünme kaç farklı biçimde yapılabilir?', '15', ['90', '45', '720'], 'Adlı gruplar için C(6, 2) · C(4, 2) · C(2, 2) = 90. Gruplar adsız olduğundan 3! = 6\'ya bölünür: 15.'),
  ('9 öğrenci, laboratuvarda aynı büyüklükte ve adsız üç masaya üçer kişi oturacak biçimde kaç farklı yolla dağıtılabilir?', '280', ['1680', '84', '560'], 'Adlı gruplar için C(9, 3) · C(6, 3) · C(3, 3) = 84 · 20 = 1680. Gruplar adsız olduğundan 3! = 6\'ya bölünür: 280.'),
  ('Bir satranç tahtasına (8 × 8) birbirini tehdit etmeyecek biçimde, yani aynı satırda ya da sütunda bulunmayacak şekilde 2 farklı renkli kale kaç farklı yolla yerleştirilebilir?', '3136', ['1568', '784', '3584'], 'Beyaz kale 64 kareden birine konur; siyah kale, beyazın satır ve sütunu dışındaki 7 · 7 = 49 kareden birine konar. 64 · 49 = 3136.'),
  ('52 kartlık bir desteden çekilen 5 kartın hepsinin kupa olma olasılığı kaçtır?', '33/66640', ['1/2598960', '1287/52', '5/52'], 'Uygun eller C(13, 5) = 1287, tüm eller C(52, 5) = 2 598 960\'tır. 1287/2598960 sadeleşince 33/66640 olur.'),
  ('52 kartlık bir desteden çekilen 5 kartlık bir elde tam olarak 2 as bulunma olasılığı kaçtır?', '2162/54145', ['1/13', '6/54145', '4324/54145'], 'İki as C(4, 2) = 6, diğer üç kart C(48, 3) = 17296 biçimde seçilir: 103776 durum. 103776/2598960 = 2162/54145.'),
  ('52 kartlık bir desteden art arda, geri koymadan iki kart çekiliyor. Çekilen iki karttan birinin as, diğerinin değeri 10 olan bir kart (10, vale, kız ya da papaz) olma olasılığı, hangi sırayla geldikleri önemsenmeden kaçtır?', '32/663', ['1/13', '32/1326', '16/221'], 'As ve 10 değerli 16 karttan biri iki sırayla gelebilir: 2 · (4/52)(16/51) = 128/2652 = 32/663.'),
  ('1\'den 10\'a kadar numaralanmış on top içinden aynı anda dört top çekiliyor. Çekilen numaraların en küçüğünün 3 olma olasılığı kaçtır?', '1/6', ['1/5', '1/7', '2/21'], 'En küçük 3 ise kalan üç top 4–10 arasındaki 7 numaradan seçilir: C(7, 3) = 35. Tüm durumlar C(10, 4) = 210; 35/210 = 1/6.'),
  ('1\'den 10\'a kadar numaralanmış on top içinden aynı anda üç top çekiliyor. Numaraların ortancasının (ortadaki değerin) 5 olma olasılığı kaçtır?', '1/6', ['1/5', '1/12', '1/10'], 'Ortanca 5 ise bir sayı 1–4 arasından (4 seçenek), biri 6–10 arasından (5 seçenek) gelir: 20 durum. Tüm durumlar C(10, 3) = 120; 20/120 = 1/6.'),
  ('İki hilesiz zar atılıyor. Zarlardan birinin sayısının diğerine tam bölündüğü (ya da eşit olduğu) sonuçların olasılığı kaçtır?', '11/18', ['11/180', '5/9', '13/18'], 'Uygun sonuçlar: 6 eşit çift, ayrıca (1,b) ve (a,1) gibi bölünenler ile (2,4), (4,2), (2,6), (6,2), (3,6), (6,3) toplam 22 sonuç. 22/36 = 11/18.'),
  ('Bir oyunda A\'nın kazanma olasılığı 1/3, B\'nin kazanma olasılığı 2/3\'tür. A kazanırsa B, A\'ya 10 TL öder; B kazanırsa A, B\'ye x TL öder. Oyunun adil olması (beklenen kazancın sıfır olması) için x kaç TL olmalıdır?', '5', ['10', '20', '2,5'], 'A\'nın beklenen kazancı (1/3) · 10 − (2/3) · x = 0 olmalıdır. Buradan 10/3 = 2x/3 ve x = 5 bulunur.'),
  ('Hilesiz bir madeni para 5 kez atılıyor. Yazı sayısının tek olma olasılığı kaçtır?', '1/2', ['3/8', '5/16', '1/4'], 'Para simetrik olduğundan yazı sayısı çift ya da tek olmaları eş olasılıklıdır; toplam 2⁵ dizinin yarısı, 16 dizi, tek yazılıdır. Olasılık 1/2.'),
  ('5 kişi, şapkalarını bırakıp rastgele birer şapka alıyor. Tam 3 kişinin kendi şapkasını alma olasılığı kaçtır?', '1/12', ['1/10', '1/20', '1/120'], 'Kendi şapkasını alacak 3 kişi C(5, 3) = 10 biçimde seçilir; kalan 2 kişinin ikisi de yanlış şapka alacaksa tek durum vardır (yer değiştirirler). 10/120 = 1/12.'),
  ('Beş misafir kapıda bıraktığı şapkalardan rastgele birer şapka alıyor. Dördünün kendi şapkasını, beşincisinin ise başkasının şapkasını almış olma olasılığı kaçtır?', '0', ['1/120', '1/5', '1/24'], '4 kişi kendi şapkasını almışsa kalan beşinci kişiye de kendi şapkası kalır; yani tam 4 doğru olamaz. Olasılık 0.'),
  ('1, 2, 3, 4, 5 rakamlarının her biri bir kez kullanılarak yazılan beş basamaklı sayılar küçükten büyüğe sıralandığında 34. sayı hangisidir?', '23451', ['23415', '23541', '24135'], '1 ile başlayan 24 sayıdan sonra 2 ile başlayanlar gelir; 25–30. sayılar 21xxx, 31–36. sayılar 23xxx. 23xxx\'in 4. sayısı 23451\'dir.'),
  ('KALEM sözcüğünün harfleri ile yazılabilen tüm (anlamlı ya da anlamsız) beş harfli sözcükler Türk alfabesindeki sıraya göre (A, E, K, L, M) dizildiğinde KALEM sözcüğü kaçıncı sırada yer alır?', '51', ['49', '120', '48'], 'K ile başlayanlardan önce A ve E ile başlayan 2 · 24 = 48 sözcük vardır. KA ile başlayanlarda sıra KAELM, KAEML, KALEM biçimindedir; KALEM 51. sıradadır.'),
  ('İki çocuklu bir ailede büyük çocuğun kız olduğu biliniyor. Küçük çocuğun da kız olma olasılığı kaçtır? (Her doğumda kız ve erkek eş olasılıklıdır.)', '1/2', ['1/3', '1/20', '2/3'], 'Bilgi yalnız büyük çocuğu belirlediğinden küçük çocuk bundan bağımsızdır; olasılığı 1/2\'dir. ("En az biri kız" bilgisi verilseydi sonuç 1/3 olurdu.)'),
  ('Bir zar iki kez atıldığında, "ilk atışta çift sayı" ve "toplamın 7 olması" olayları için hangisi doğrudur?', 'Bağımsızdır', ['Ayrıktır', 'Biri diğerinin alt kümesidir', 'Birbirinin tümleyenidir'], 'P(ilk çift) = 1/2, P(toplam 7) = 1/6 ve P(ikisi) = 3/36 = 1/12 olup çarpıma eşittir. Bu nedenle olaylar bağımsızdır.'),
  ('2 × 5 birim boyutundaki bir dikdörtgen, 1 × 2 boyutlu dominolarla örtüşmeden ve boşluk bırakmadan kaç farklı biçimde kaplanabilir?', '8', ['5', '10', '32'], '2 × n kaplamalarının sayısı Fibonacci kuralını izler: n = 1, 2, 3, 4, 5 için 1, 2, 3, 5, 8. Dolayısıyla 2 × 5 için 8 kaplama vardır.'),
  ('Bir kişi sekiz gün boyunca her gün çay ya da kahve içiyor ve hiçbir iki ardışık günde kahve içmiyor. Kaç farklı içecek programı yapılabilir?', '55', ['34', '89', '128'], 'Ardışık iki kahvenin bulunmadığı n günlük dizilerin sayısı Fibonacci kuralıyla artar: 2, 3, 5, 8, 13, 21, 34, 55. Sekiz gün için 55 program vardır.'),
  ('10 TL\'lik bir tutar, yalnız 1 TL, 2 TL ve 5 TL\'lik paralarla (sayıları sınırsız) paraların sırası önemsenmeden kaç farklı yolla ödenebilir?', '10', ['8', '12', '100'], '5 TL\'lik para sayısı c için: c = 0 iken 1 ve 2 TL ile 10 TL (6 yol), c = 1 iken 5 TL (3 yol), c = 2 iken 1 yol. 6 + 3 + 1 = 10.'),
  ('4 evli çiftten hiçbir çiftin iki eşi birlikte bulunmayacak biçimde 4 kişilik bir komite kaç farklı yolla kurulabilir?', '16', ['70', '24', '8'], 'Komite, her çiftten en çok bir kişi içereceğinden 4 kişi 4 çiftten birer kişidir. Her çiftte 2 seçim vardır: 2⁴ = 16.'),
  ('5 evli çiftin bulunduğu bir gruptan, içinde evli çift bulunmayacak biçimde 3 kişilik bir ekip kaç farklı yolla seçilebilir?', '80', ['120', '60', '100'], 'Önce 3 çift C(5, 3) = 10 yolla seçilir, ardından her çiftten bir kişi 2³ = 8 yolla seçilir. 10 · 8 = 80.'),
  ('{1, 2, ..., 10} kümesinden seçilen üç farklı sayının toplamı 3\'e tam bölünebiliyor. Kaç farklı üçlü bu koşulu sağlar?', '42', ['40', '36', '120'], 'Kalanlara göre sayılar: 3 tanesi 0, 4 tanesi 1, 3 tanesi 2 kalanlı. Uygun üçlüler: C(3,3) + C(4,3) + C(3,3) + 3 · 4 · 3 = 1 + 4 + 1 + 36 = 42.'),
  ('İki paralel koldan oluşan bir devrenin her kolunda seri bağlı ikişer eleman vardır. Her elemanın bağımsız olarak çalışma olasılığı 0,9\'dur. Devrenin akım geçirme olasılığı kaçtır?', '0,9639', ['0,09639', '0,9900', '0,9801'], 'Bir kolun çalışması 0,9 · 0,9 = 0,81\'dir. İki paralel koldan hiçbirinin çalışmaması 0,19² = 0,0361\'dir. Devre olasılığı 1 − 0,0361 = 0,9639.'),
  ('100 ürünün 5\'i kusurludur. Rastgele ve aynı anda seçilen 3 ürünün hiçbirinin kusurlu olmama olasılığı yaklaşık kaçtır?', '0,856', ['0,900', '0,950', '0,0856'], 'Uygun durumlar C(95, 3), toplam durumlar C(100, 3)\'tür; oran (95 · 94 · 93)/(100 · 99 · 98) ≈ 0,856. İade varsayımı 0,95³ ≈ 0,857 verirdi, ancak ürünler aynı anda seçildiği için kesin değer 0,856\'dır.'),
  ('Hilesiz bir madeni para ilk yazı gelene kadar atılıyor. İlk yazının çift sayıdaki bir atışta gelme olasılığı kaçtır?', '1/3', ['1/2', '1/30', '1/4'], 'İlk yazı 2., 4., 6., ... atışta gelirse olasılık (1/2)² + (1/2)⁴ + ... = (1/4)/(1 − 1/4) = 1/3.'),
  ('Üç kart vardır: biri iki yüzü de kırmızı, biri iki yüzü de mavi, biri bir yüzü kırmızı bir yüzü mavidir. Rastgele bir kart seçilip rastgele bir yüzü masaya konuyor ve görünen yüzün kırmızı olduğu görülüyor. Kartın diğer yüzünün de kırmızı olma olasılığı kaçtır?', '2/3', ['1/2', '1/3', '3/4'], 'Altı yüzden üçü kırmızıdır; bunların ikisi iki yüzü kırmızı kartın yüzleridir. Koşullu olasılık 2/3\'tür (sezgisel 1/2 yanlıştır).'),
  ('Bir torbada 50 kırmızı ve 50 mavi top vardır. Geri konmadan art arda iki top çekiliyor. İki topun aynı renkte olma olasılığı kaçtır?', '49/99', ['1/2', '49/198', '25/99'], 'İlk top ne olursa olsun, ikinci topun aynı renkte olması için kalan 99 toptan 49\'u uygundur. Olasılık 49/99.'),
  ('İki hilesiz zar atılıyor. Zarlardaki sayıların çarpımının toplamlarından büyük olma olasılığı kaçtır?', '2/3', ['1/2', '5/9', '7/12'], 'Çarpım > toplam eşitsizliği (a − 1)(b − 1) > 1 biçimine gelir. Uygun olmayanlar a = 1 ya da b = 1 (11 sonuç) ile (2, 2) olmak üzere 12 sonuçtur. 24/36 = 2/3.'),
  ('SAKARYA sözcüğünün harfleri yer değiştirilerek A harflerinden hiçbirinin başka bir A ile yan yana gelmediği kaç farklı dizilim yazılabilir?', '240', ['2400', '120', '480'], 'Dört farklı sessiz harf 4! = 24 biçimde dizilir. Aralarındaki ve uçlardaki 5 boşluktan 3\'ü A\'lar için C(5, 3) = 10 biçimde seçilir. 24 · 10 = 240.'),
  ('Bir gezgin satıcı, başlangıç şehri sabit olmak üzere 5 şehrin hepsini birer kez dolaşıp başladığı şehre dönecektir. Rotanın yönü önemsenmezse (ters yönde gidiş aynı sayılırsa) kaç farklı rota vardır?', '12', ['24', '120', '60'], 'Başlangıç sabitken kalan 4 şehir 4! = 24 sırayla gezilir. Ters yönden gidiş aynı rotayı verdiğinden 24/2 = 12.'),
  ('Her satır ve sütununda 1, 2 ve 3 sayılarının birer kez bulunduğu 3 × 3\'lük kaç farklı "Latin kare" yazılabilir?', '12', ['6', '9', '24'], 'İlk satır 3! = 6 biçimdedir; her ilk satır için ikinci satırın 2 uygun dizilişi (kaydırmalar) vardır. Sonrası belirlenir: 6 · 2 = 12.'),
  ('5 sayısı, sırası önemsenerek pozitif tam sayıların toplamı olarak (örneğin 2 + 3 ile 3 + 2 farklı sayılır) kaç farklı biçimde yazılabilir?', '16', ['7', '160', '10'], 'n sayısının sıralı parçalanışları, toplamdaki n − 1 "artı" konumunun her birinde ayırma ya da ayırmama seçeneğiyle belirlenir: 2ⁿ⁻¹. n = 5 için 2⁴ = 16.'),
  ('Karşılıklı yüzlerinin toplamı 7 olan standart bir zar, dönmelerle çakışanlar aynı sayılırsa kaç farklı biçimde numaralandırılabilir?', '2', ['1', '6', '24'], 'Bir köşedeki üç yüz 1, 2, 3 olarak sabitlenirse saat yönü ya da ters yönü seçilebilir. Bu iki zar birbirinin ayna görüntüsüdür ve dönmeyle çakışmaz; 2 biçim vardır.'),
  ('(1 + x)ⁿ açılımında ardışık üç terimin katsayıları 1 : 2 : 3 oranındadır. n kaçtır?', '14', ['12', '140', '16'], 'C(n, k) : C(n, k+1) = 1 : 2 ve C(n, k+1) : C(n, k+2) = 2 : 3 koşullarından k = 4 ve n = 14 bulunur; katsayılar 1001, 2002 ve 3003\'tür.'),
  ('Chevalier de Méré, bir zarla dört atışta en az bir kez 6 gelmesine bahis oynamayı karlı, iki zarla 24 atışta en az bir kez çift 6 gelmesine bahis oynamayı ise aynı ölçüde karlı sanıyordu. Gerçek olasılıklar için hangisi doğrudur?', 'Birincisi ≈ 0,518, ikincisi ≈ 0,491\'dir', ['İkisi de tam olarak 0,5\'tir', 'Birincisi ≈ 0,491, ikincisi ≈ 0,518\'dir', 'İkisi de 0,6\'nın üzerindedir'], '1 − (5/6)⁴ ≈ 0,518 ve 1 − (35/36)²⁴ ≈ 0,491 olduğundan ikinci bahis kaybettiricidir. Bu fark Pascal\'la yazışmanın başlangıç noktası olmuştur.'),
  ('Çember üzerindeki noktaların her çiftini, kimlerin "tanışıp tanışmadığına" göre iki renkten biriyle boyayan 6 kişilik bir grupta, tek renkli bir üçgen oluştuğunu (yani üçü karşılıklı tanışan ya da üçü karşılıklı tanışmayan kişiler bulunduğunu) kanıtlayan ilke hangisine dayanır?', 'Güvercin yuvası ilkesine', ['Büyük Sayılar Yasası\'na', 'Bayes teoremine', 'Binom teoremine'], 'Bir kişi diğer 5 kişiden en az 3\'üyle aynı renkli bağa sahiptir (güvercin yuvası); bu üç kişinin kendi aralarındaki bağlar da tek renkli üçgeni tamamlar.'),
  ('İki hilesiz zar atılıyor. Zarların büyüğünün (iki sayıdan büyük olanın) beklenen değeri kaçtır?', '161/36', ['7/2', '4', '49/12'], 'Büyük sayının k olma olasılığı (2k − 1)/36\'dır. E = Σ k(2k − 1)/36 = (1 + 6 + 15 + 28 + 45 + 66)/36 = 161/36 ≈ 4,47.'),
  ('Bir oyuncak firması, 3 farklı koleksiyon kartının birer tanesini içeren bir koleksiyon serisi üretiyor ve her paketten bu 3 karttan biri eşit olasılıkla çıkıyor. Hepsini tamamlamak için gereken beklenen paket sayısı kaçtır?', '5,5', ['6', '4,5', '5,05'], 'İlk yeni kart 1, ikinci yeni kart 3/2, üçüncü yeni kart 3 paket gerektirir (ortalama): 1 + 1,5 + 3 = 5,5.'),
  ('6 kadın ve 9 erkekten en az bir erkek içeren 3 kişilik bir ekip kurulacaktır. Bir öğrenci "önce bir erkek seçeyim, kalan 14 kişiden 2\'sini seçeyim: 9 · C(14, 2)" diyor. Bu yaklaşım için hangisi doğrudur?', 'Aynı ekibi birden fazla kez saydığından yanlıştır', ['Doğrudur, çünkü her ekip bir erkek içerir', 'Yalnız erkek sayısı 3\'ten fazlaysa doğrudur', 'Doğrudur, ancak sonuç ikiye bölünmelidir'], 'Birden fazla erkek içeren ekip, o erkeklerden her biri "ilk seçilen" sayıldığında birden çok kez sayılır. Doğru yol 455 − C(6, 3) = 435\'tir.'),
  ('Bir küpün altı yüzü iki renkle (kırmızı ve mavi) boyanacak ve döndürülünce birbirine çakışan boyamalar aynı sayılacaktır. Kaç farklı küp elde edilir?', '10', ['64', '8', '12'], 'Burnside lemmasına göre 24 dönmenin sabit bıraktığı boyamalar sayılır: 64 + 6·8 + 3·16 + 8·4 + 6·8 = 240. 240/24 = 10 farklı küp elde edilir.'),
  ('3 mavi ve 3 kırmızı boncuk, altı noktalı bir daire biçimindeki halkaya dizilecektir. Döndürülünce çakışan dizilişler aynı sayılırsa kaç farklı halka elde edilir?', '4', ['3', '5', '20'], 'Toplam C(6, 3) = 20 dizilişin dönmelerle oluşan gruplarının sayısı 4\'tür: 000111, 001011, 001101 ve 010101 türleri.'),
  ('Bir çember üzerinde 5 nokta işaretlenip her ikisi bir kirişle birleştiriliyor. Kirişlerin hiçbir üçü iç bir noktada kesişmiyorsa çember içi en çok kaç bölgeye ayrılır?', '16', ['11', '10', '26'], 'Bölge sayısı 1 + C(n, 2) + C(n, 4) bağıntısıyla bulunur: 1 + 10 + 5 = 16.'),
  ('Bir küpün 12 ayrıtı arasında birbirine paralel olan kaç farklı ayrıt çifti vardır?', '18', ['12', '24', '180'], 'Küpün ayrıtları üç yönde ve her yönde 4 paralel ayrıt bulunur. Her yönde C(4, 2) = 6 çift vardır; 3 · 6 = 18.'),
  ('Düzgün bir sekizgenin köşelerinden üçü seçilerek oluşturulan üçgenlerden kaç tanesi dik üçgendir?', '24', ['16', '32', '240'], 'Çapı gören çevre açı dik açı olduğundan dik üçgenin hipotenüsü bir çaptır. 4 çap vardır ve her biri için kalan 6 köşeden biri seçilir: 4 · 6 = 24.'),
  ('Düzgün bir on iki genin köşelerinden üçü seçilerek oluşturulan eşkenar üçgenlerin sayısı kaçtır?', '4', ['3', '6', '12'], 'Eşkenar üçgenin köşeleri 12 genin köşelerinden dörder birim arayla seçilir. Başlangıç köşesi 4 farklı eşkenar üçgen belirler (0, 4, 8; 1, 5, 9; 2, 6, 10; 3, 7, 11).'),
  ('Düzgün bir dokuzgenin köşelerinden üçü seçilerek oluşturulan, ikizkenar ama eşkenar olmayan üçgenlerin sayısı kaçtır?', '27', ['30', '36', '24'], 'Her köşe tepe olmak üzere eşit kenar yaylarının 1, 2, 3, 4 olduğu 4 üçgen oluşur; yay 3 olunca eşkenar üçgen elde edilir. Eşkenar olmayan 3 üçgen × 9 köşe = 27.'),
  ('4 mektup 4 zarfa rastgele yerleştiriliyor. Tam bir mektubun kendi zarfında olduğu kaç farklı yerleştirme vardır?', '8', ['9', '6', '16'], 'Doğru yerleşen mektup 4 biçimde seçilir; kalan 3 mektubun hiçbiri kendi zarfında olmaz (D₃ = 2 yolla). 4 · 2 = 8.'),
  ('Üç hilesiz zar atılıyor. Üç sayının en küçüğünün tam 3 olma olasılığı kaçtır?', '37/216', ['8/27', '27/216', '1/6'], 'En küçük en az 3 olma durumu (4/6)³ = 64/216, en küçük en az 4 olma durumu (3/6)³ = 27/216\'dır. Fark 37/216.'),
  ('20 öğrenci, her grupta 5 kişi olacak biçimde rastgele 4 gruba ayrılıyor. İki arkadaşın aynı grupta olma olasılığı kaçtır?', '4/19', ['4/190', '5/20', '1/5'], 'Birinci arkadaşın grubu belli olunca, ikinci arkadaşın o grupta kalan 4 yerden birine denk gelmesi gerekir: 4/19.'),
  ('ANKARA sözcüğünün harfleri rastgele diziliyor. Üç A harfinin birbirine bitişik olma olasılığı kaçtır?', '1/5', ['1/6', '1/10', '1/20'], 'Toplam dizilim 6!/3! = 120\'dir. AAA bir blok sayılırsa 4 öğe 4! = 24 biçimde dizilir. 24/120 = 1/5.'),
  ('Birim kareden (x, y ∈ [0, 1]) rastgele ve bağımsız olarak seçilen iki sayının çarpımının 1/2\'den küçük olma olasılığı kaçtır?', '(1 + ln 2)/2', ['1/2', '1/4', 'ln 2'], 'P(xy < c) = c(1 − ln c) olduğundan c = 1/2 için (1/2)(1 + ln 2) ≈ 0,847\'dir.'),
  ('Hilesiz bir madeni paranın ikinci yazısının tam dördüncü atışta gelme olasılığı kaçtır?', '3/16', ['1/4', '1/8', '3/160'], 'İlk üç atışta tam 1 yazı: C(3, 1) = 3 dizi; dördüncü atış yazı. Toplam 3 · (1/2)⁴ = 3/16.'),
  ('24 saatlik bir dijital saatte (00:00–23:59) ekranda görünen dört rakam, soldan ve sağdan okunduğunda aynı çıkıyorsa (örneğin 12:21) bu tür kaç farklı an vardır?', '16', ['12', '160', '18'], 'Saat 00–05, 10–15 ve 20–23 olduğunda dakikalar saatin ters yazılışı olup 59\'u aşmaz. 6 + 6 + 4 = 16 an vardır.'),
  ('n = 10 ve p = 0,3 olan bir binom dağılımında olasılığı en büyük olan başarı sayısı kaçtır?', '3', ['4', '2', '7'], 'Ardışık olasılıkların oranı (n − k)p/((k + 1)(1 − p)) 1\'e eşit ya da küçük olana kadar artar; k = 3\'te olasılık en büyüktür (≈ 0,267).'),
  ('P(A) = 0,4 ve P(B) = 0,3 olan iki olay için P(A ∪ B) hangi aralıkta bulunabilir?', '0,4 ≤ P(A ∪ B) ≤ 0,7', ['0,3 ≤ P(A ∪ B) ≤ 0,4', '0 ≤ P(A ∪ B) ≤ 0,7', '0,7 ≤ P(A ∪ B) ≤ 1'], 'Birleşim en az büyük olasılıktan (0,4) ve en çok olasılıkların toplamından (0,7, olaylar ayrıksa) oluşur.'),
  ('A ve B bağımsız olaylar ise A ile B\'nin tümleyeni olan B\' olayları hakkında aşağıdakilerden hangisi doğrudur?', 'A ve B\' de bağımsızdır', ['A ve B\' ayrıktır', 'A ve B\' birbirinin tümleyenidir', 'A ve B\' mutlaka eş olasılıklıdır'], 'P(A ∩ B\') = P(A) − P(A ∩ B) = P(A) − P(A)P(B) = P(A)(1 − P(B)) = P(A)P(B\'); dolayısıyla bağımsızdır.'),
  ('Olasılığı 0 olan bir A olayı için, başka herhangi bir B olayıyla bağımsızlık hakkında ne söylenebilir?', 'Her B ile bağımsızdır', ['Hiçbir B ile bağımsız olamaz', 'Yalnız ayrık B\'lerle bağımsızdır', 'Yalnız B = A ise bağımsızdır'], 'P(A ∩ B) ≤ P(A) = 0 olduğundan P(A ∩ B) = 0 = P(A) · P(B) olur; A her olayla bağımsızdır.'),
  ('6 özdeş bilye 3 farklı çocuğa, hiçbir çocuk 3\'ten fazla bilye almayacak biçimde kaç yolla dağıtılabilir?', '10', ['100', '18', '6'], 'Kısıtsız dağıtımlar C(8, 2) = 28\'dir. Bir çocuğun en az 4 bilye aldığı dağıtımlar 3 · C(4, 2) = 18\'dir. İki çocuk aynı anda 4 alamayacağından 28 − 18 = 10.'),
  ('x₁ + x₂ + x₃ = 9 denklemini sağlayan, her biri en az sıfır olan ve x₁ ≤ 2 koşulunu da sağlayan tam sayı üçlüleri kaç tanedir?', '27', ['270', '11', '36'], 'x₁ = 0 iken 10, x₁ = 1 iken 9, x₁ = 2 iken 8 çözüm vardır (x₂ + x₃ = 9 − x₁). 10 + 9 + 8 = 27.'),
  ('1 ≤ a ≤ b ≤ c ≤ 4 koşulunu sağlayan kaç tane (a, b, c) tam sayı üçlüsü vardır?', '20', ['24', '64', '16'], 'Sıralanmış ve tekrar edebilen 3 değer, 4 değerden seçilir: C(4 + 3 − 1, 3) = C(6, 3) = 20.'),
  ('Çarpımı 12 olan sıralı pozitif tam sayı üçlüleri (a, b, c) kaç tanedir?', '18', ['12', '24', '180'], '12 = 2² · 3 olduğundan 2\'nin kuvvetleri üç değişkene C(4, 2) = 6 yolla, 3 ise 3 yolla dağıtılır. 6 · 3 = 18.'),
  ('Altı farklı rakam kartı (1, 2, 3, 4, 5, 6) yan yana dizilerek altı basamaklı sayılar oluşturuluyor. Oluşan sayılardan dörde tam bölünebilenler kaç tanedir?', '192', ['180', '216', '144'], 'Son iki basamak 4\'ün katı olmalıdır: 12, 16, 24, 32, 36, 52, 56, 64 (8 çift). Kalan 4 rakam 4! = 24 biçimde dizilir. 8 · 24 = 192.'),
  ('Beş farklı rakam kartı (0, 1, 2, 3, 4) yan yana dizilerek ilk rakamı sıfır olmayan beş basamaklı sayılar oluşturuluyor. Bunlardan çift olanlar kaç tanedir?', '60', ['48', '72', '120'], 'Birler basamağı 0 ise 4! = 24 sayı vardır. Birler basamağı 2 ya da 4 ise başa 0 gelemeyeceğinden 3 · 3! = 18 sayı vardır; iki seçim için 36. Toplam 24 + 36 = 60.'),
  ('İki takım arasında yedi maçlık bir seride (4 maç kazanan seriyi alır) takımlar eşit güçlüdür. Serinin tam yedinci maça gitme olasılığı kaçtır?', '5/16', ['5/160', '1/4', '3/8'], 'Yedinci maça gitmek için ilk altı maç 3-3 bitmelidir: C(6, 3)/2⁶ = 20/64 = 5/16.'),
  ('Bir takımın bağımsız her maçı kazanma olasılığı 0,6\'dır. Üç galibiyeti alanın seriyi kazandığı beş maçlık seride bu takımın seriyi kazanma olasılığı kaçtır?', '0,68256', ['0,64800', '0,59049', '0,77760'], 'Seriyi 3-0, 3-1 ve 3-2 kazanma olasılıkları 0,6³(1 + 3 · 0,4 + 6 · 0,4²) = 0,216 · 3,16 = 0,68256\'dır.'),
  ('1\'den 100\'e kadar numaralanmış 100 karttan aynı anda 3 kart çekiliyor. Üç kartın da çift numaralı olma olasılığı kaçtır?', '4/33', ['1/8', '1/9', '4/330'], 'Uygun durumlar C(50, 3) = 19600, tüm durumlar C(100, 3) = 161700\'dür. Oran 19600/161700 = 4/33.'),
  ('Rastgele yerleştirilmiş 16 takımlı tek maçlık eleme turnuvasında iki belirli takımın turnuva boyunca bir kez karşılaşma olasılığı kaçtır?', '1/8', ['1/16', '1/15', '1/4'], 'Turnuvada toplam 15 maç oynanır ve her maç farklı bir takım çiftidir. Çiftlerin toplamı C(16, 2) = 120\'dir; simetri gereği belirli bir çiftin karşılaşma olasılığı 15/120 = 1/8.'),
  ('Hilesiz bir zar 4 kez atılıyor. En az iki kez 6 gelme olasılığı yaklaşık kaçtır?', '0,132', ['0,518', '0,386', '0,0132'], 'Tümleyen: hiç 6 gelmeme (5/6)⁴ ≈ 0,482 ve tam bir kez 4 · (1/6)(5/6)³ ≈ 0,386. En az iki kez 1 − 0,482 − 0,386 ≈ 0,132.'),
  ('Bir çalışan, pazartesiden pazara sıralanmış haftanın 7 gününden ardışık olmayan 3 günü izin günü olarak seçecektir (pazar ile ertesi haftanın pazartesisi dikkate alınmaz, yani günler doğrusal sıralıdır). Kaç farklı seçim yapabilir?', '10', ['35', '20', '15'], 'Ardışık olmayan r seçim için C(n − r + 1, r) kullanılır: C(5, 3) = 10.'),
  ('7 gün bir çember üzerinde ardışık sayılırsa (pazar günü ile pazartesi de komşudur), hiçbir ikisi komşu olmayan 3 gün kaç farklı yolla seçilebilir?', '7', ['10', '14', '35'], 'Dairesel düzende uygun seçim sayısı n/(n − r) · C(n − r, r) = 7/4 · C(4, 3) = 7\'dir.'),
  ('1\'den 20\'ye kadar sayılar arasından 11 farklı sayı seçiliyor. Seçilenler arasında mutlaka ardışık iki sayı bulunduğu nasıl açıklanır?', '1–20 sayıları (1,2), (3,4), ..., (19,20) biçiminde 10 çifte bölünür; 11 sayıdan ikisi aynı çifte düşer', ['20 sayının yarısı çift olduğundan en az biri çifttir', '11 sayı her zaman bir aritmetik dizi oluşturur', 'Sayılar birbirinden en az 2 farklıysa yalnız 10 sayı seçilemez'], 'Sayılar 10 çifte bölünür; güvercin yuvası ilkesiyle 11 sayıdan ikisi aynı çiftte olur ve bunlar ardışıktır.'),
  ('1\'den 100\'e kadar sayılar arasından 51 farklı sayı seçildiğinde, seçilenler arasında biri diğerine tam bölünen iki sayı bulunması hangi fikre dayanır?', 'Her sayı tek çarpan ve 2\'nin kuvvetinin çarpımıdır; 50 tek çarpan için 51 sayıdan ikisi aynı tek çarpanı paylaşır', ['Her sayı 2 ile bölünebilir', '100 sayının çarpanları çifttir', '51 sayı bir asal sayı içerir'], 'Her sayı 2ᵏ · m (m tek) biçiminde yazılır. 1–100 arasında 50 farklı tek m vardır; 51 sayıdan ikisinin m\'si eşit olur ve küçüğü büyüğünü böler.'),
  ('6 farklı renkteki boncuk, bir ipe dizilip uçları birleştirilerek bilezik yapılacaktır. Bilezik çevrilip ters yüz edilebiliyorsa kaç farklı bilezik yapılabilir?', '60', ['120', '720', '30'], 'Dairesel dizilişler (6 − 1)! = 120\'dir. Ters yüz edilince aynı olan ayna görüntüleri bir sayıldığından 120/2 = 60.'),
  ('Bir hakim, bir tanığın tesadüfen ortaya çıkma olasılığının 1/1000 olduğu kanıtı için "suçsuzluk olasılığı 1/1000\'dir" diyor. Bu akıl yürütmedeki yanılgı hangisidir?', 'P(kanıt | suçsuz) ile P(suçsuz | kanıt) birbirine eşitmiş gibi alınmıştır', ['Kanıtın olasılığı hiç hesaplanmamıştır', 'Olasılıklar toplamı 1\'i geçmiştir', 'Olasılık 1/1000 olduğu için olay imkânsız sayılmıştır'], 'Koşullu olasılık simetrik değildir. Taban oranı ve kanıtın diğer açıklamalarını içeren Bayes hesabı olmadan P(suçsuz | kanıt) bilinemez (savcı yanılgısı).'),
  ('Hilesiz bir zar iki kez atılıyor. Gelen iki sayının toplamının varyansı kaçtır?', '35/6', ['35/12', '7/2', '49/12'], 'Bağımsız değişkenlerde varyanslar toplanır; tek zarın varyansı 35/12\'dir. 2 · 35/12 = 35/6.'),
  ('Düzgün altıgen şeklindeki bir hedefe rastgele atılan okun, altıgenin içine çizilmiş çembere (iç teğet) isabet etme olasılığı kaçtır? (Altıgenin kenarı a\'dır.)', 'π/(2√3)', ['π/3', '√3/π', 'π/4'], 'Altıgenin alanı (3√3/2)a², iç teğet çemberin yarıçapı (√3/2)a olduğundan alanı (3π/4)a²\'dir. Oran (3π/4)/(3√3/2) = π/(2√3) ≈ 0,907.'),
  ('6 kişi yan yana sıralanacaktır. Ayşe\'nin en başta, Barış\'ın ise en sonda bulunmadığı kaç farklı sıralama vardır?', '504', ['480', '600', '720'], 'Toplam 720 sıralamadan Ayşe\'nin en başta olduğu 5! = 120 ve Barış\'ın en sonda olduğu 120 durum çıkarılır, ikisinin birlikte olduğu 4! = 24 durum geri eklenir. 720 − 240 + 24 = 504.'),
  ('Bir küpün 8 köşesinden dördü seçiliyor. Seçilen dört köşenin aynı düzlemde bulunmadığı kaç farklı seçim vardır?', '58', ['70', '12', '64'], 'Tüm seçimler C(8, 4) = 70\'tir. Aynı düzlemde olanlar 6 yüz ve 6 köşegen düzlemiyle 12 tanedir. 70 − 12 = 58.'),
];
